import{_ as r,o,c as a,a2 as n}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"FrequencyTrack","description":"","frontmatter":{"title":"FrequencyTrack","order":8},"headers":[],"relativePath":"zh/mods/freqtrack.md","filePath":"zh/mods/freqtrack.md","lastUpdated":1786943111000}'),e={name:"zh/mods/freqtrack.md"};function d(s,t,i,l,g,c){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="frequencytrack" tabindex="-1">FrequencyTrack <a class="header-anchor" href="#frequencytrack" aria-label="Permalink to &quot;FrequencyTrack&quot;">​</a></h1><p><strong>频率轨道铺设工具</strong> —— ADOFAI 编辑器 Mod。按频率（音高）在轨道上自动铺设砖块，支持<strong>固定频率段</strong>、<strong>滑音（频率渐变）<strong>与</strong>噪音段</strong>三种生成方式，并<strong>自动变速</strong>使音高与 BPM 精确匹配（0 误差）。</p><blockquote><p>所属：<code>adofaiex/ADOFAIMods</code> 仓库中的 <strong>EditorExtensions</strong> 模组（Unity Mod Manager 格式）。FreqTrack 由 StArray 与 AI 助手共同研发。</p></blockquote><h2 id="安装与启用" tabindex="-1">安装与启用 <a class="header-anchor" href="#安装与启用" aria-label="Permalink to &quot;安装与启用&quot;">​</a></h2><ol><li>将编译好的 <code>EditorExtensions</code> Mod 放入 ADOFAI 的 <code>Mods</code> 目录</li><li>游戏内打开 <strong>Mod 设置</strong>（Unity Mod Manager 窗口）</li><li>勾选 <strong>启用频率轨道铺设工具</strong>（Enable FreqTrack）</li><li>可选：切换 <strong>英文 / 中文</strong> 语言；勾选 <strong>启用频率轨道日志</strong> 输出详细调试日志（默认关闭）</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>切换语言后面板文字会实时刷新（含字体切换：英文 SourceSans3 / 中文思源黑体）。</p></div><h2 id="打开面板" tabindex="-1">打开面板 <a class="header-anchor" href="#打开面板" aria-label="Permalink to &quot;打开面板&quot;">​</a></h2><p>在 ADOFAI 编辑器中，<strong>切换角度输入模式</strong>（<code>ToggleAngleInputMode</code>，编辑器左下角的「角度」按钮）时，FreqTrack 面板会自动显示 / 隐藏。</p><p>面板需要配合<strong>选中一个起始砖块</strong>使用 —— 生成的砖块会从当前选中砖块之后插入。</p><h2 id="面板界面" tabindex="-1">面板界面 <a class="header-anchor" href="#面板界面" aria-label="Permalink to &quot;面板界面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>控件</th><th>说明</th></tr></thead><tbody><tr><td>折叠按钮 <code>▼ / ▶</code></td><td>展开 / 收起面板内容</td></tr><tr><td><strong>外圈</strong></td><td>开启后按外圈（大圈）角度公式生成，频率更高时圈更大</td></tr><tr><td><strong>拍数</strong></td><td>开启后数量输入框按<strong>拍数</strong>计算；关闭时按<strong>块数</strong>计算</td></tr><tr><td><strong>起始音调</strong></td><td>十二平均律音调下拉（C0~B8，A4=440Hz），选中自动填入频率</td></tr><tr><td><strong>频率</strong></td><td>起始频率（Hz），可手动输入</td></tr><tr><td><strong>终点音调</strong></td><td>滑音终点音调下拉</td></tr><tr><td><strong>终点频率</strong></td><td>滑音终点频率（Hz）</td></tr><tr><td><strong>数量</strong></td><td>关闭拍数开关 = 目标块数；开启拍数开关 = 目标拍数</td></tr><tr><td><strong>插入拍间隔</strong></td><td>每隔 N 拍插入一个「跳变标记对」（0 = 不插入），节奏不变</td></tr><tr><td><strong>滑音缓速</strong></td><td>滑音时频率变化用的缓速函数（30 种）</td></tr><tr><td><strong>应用音调</strong></td><td>按当前频率生成一段<strong>固定频率</strong>砖块</td></tr><tr><td><strong>滑音</strong></td><td>从起始频率<strong>渐变</strong>到终点频率生成砖块</td></tr><tr><td><strong>生成噪音</strong></td><td>以当前频率为基准，每块随机偏移生成噪音段</td></tr></tbody></table><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="频率、bpm-与砖块" tabindex="-1">频率、BPM 与砖块 <a class="header-anchor" href="#频率、bpm-与砖块" aria-label="Permalink to &quot;频率、BPM 与砖块&quot;">​</a></h3><ul><li><strong>频率（Hz）= 每秒砖块数 = 显示 BPM ÷ 60</strong>。例：120 BPM → 2 块/秒 → 频率 2Hz</li><li>每块拍数 <code>TileBeats(entry, exit)</code> 由进出角度差决定：<code>((180-(exit-entry)) mod 360 + 360) mod 360 / 180</code></li></ul><h3 id="自动变速" tabindex="-1">自动变速 <a class="header-anchor" href="#自动变速" aria-label="Permalink to &quot;自动变速&quot;">​</a></h3><p>无论当前 BPM 是多少，Mod 都会在段首写入一个 <code>SetSpeed</code> 变速事件：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>newBpm = hz × 60 × TileBeats(0, segAngle)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这样<strong>游戏中听到的音高精确等于输入频率</strong>（0 误差）。外圈时每块拍数天然是 2 倍，显示 BPM 内外圈一致。</p><h3 id="角度公式" tabindex="-1">角度公式 <a class="header-anchor" href="#角度公式" aria-label="Permalink to &quot;角度公式&quot;">​</a></h3><ul><li>内圈：<code>segAngle = 180 - 180 × (hzFormBPM × bpmFactor) / hz</code></li><li>外圈：<code>segAngle = 180 - 360 × (hzFormBPM × bpmFactor) / hz</code></li><li><code>hzFormBPM</code> = 当前 BPM ÷ 60；<code>bpmFactor</code> = 以 2 为底的折叠倍率（保证角度落在合理范围）</li></ul><h3 id="音调选择器" tabindex="-1">音调选择器 <a class="header-anchor" href="#音调选择器" aria-label="Permalink to &quot;音调选择器&quot;">​</a></h3><p>基于<strong>十二平均律</strong>，参考 A4 = 440Hz，范围 C0（16.352Hz）~ B8（7902.133Hz）。选音调会自动把对应频率填入输入框，也可手动微调。</p><h2 id="功能详解" tabindex="-1">功能详解 <a class="header-anchor" href="#功能详解" aria-label="Permalink to &quot;功能详解&quot;">​</a></h2><h3 id="应用音调-——-固定频率段" tabindex="-1">应用音调 —— 固定频率段 <a class="header-anchor" href="#应用音调-——-固定频率段" aria-label="Permalink to &quot;应用音调 —— 固定频率段&quot;">​</a></h3><ol><li>选中起始砖块</li><li>选择<strong>起始音调</strong>或直接输入<strong>频率</strong></li><li>设置 <strong>数量</strong>（块数或拍数）</li><li>可选：设置 <strong>插入拍间隔</strong>（需 ≥1 的整数）</li><li>可选：开启 <strong>外圈</strong></li><li>点 <strong>应用音调</strong></li></ol><p>结果：在选中砖块后生成一段频率恒定的砖块段，自动变速，音高精确等于输入频率。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>频率 ≤ 0、输入为空时不会执行，仅弹出提示（避免产生 NaN 砖块）。</p></div><h3 id="滑音-——-频率渐变段" tabindex="-1">滑音 —— 频率渐变段 <a class="header-anchor" href="#滑音-——-频率渐变段" aria-label="Permalink to &quot;滑音 —— 频率渐变段&quot;">​</a></h3><ol><li>选中起始砖块</li><li>设置<strong>起始频率</strong>与<strong>终点频率</strong>（终点音调 / 终点频率输入框）</li><li>设置 <strong>数量</strong>（目标块数或拍数）</li><li>选择 <strong>滑音缓速</strong> 函数（默认 Linear）</li><li>可选：<strong>插入拍间隔</strong>、<strong>外圈</strong></li><li>点 <strong>滑音</strong></li></ol><p>结果：砖块角度按缓速曲线从起始频率连续渐变到终点频率，形成平滑滑音效果。</p><ul><li><strong>按拍数</strong>：生成到目标拍数为止</li><li><strong>按块数</strong>：生成到目标块数为止</li><li>变速系数按两端<strong>较低频率</strong>折叠，保证整段音高匹配</li></ul><h3 id="生成噪音" tabindex="-1">生成噪音 <a class="header-anchor" href="#生成噪音" aria-label="Permalink to &quot;生成噪音&quot;">​</a></h3><ol><li>选中起始砖块</li><li>设置<strong>起始频率</strong>和 <strong>数量</strong>（块数或拍数）</li><li>可选：<strong>外圈</strong></li><li>点 <strong>生成噪音</strong></li></ol><p>结果：以当前频率的基准角度为中心，<strong>每块随机偏移 ±25°</strong>，生成一段听觉上接近噪音的段落（节奏 / 频率基准仍与输入一致）。</p><h3 id="插入拍间隔标记" tabindex="-1">插入拍间隔标记 <a class="header-anchor" href="#插入拍间隔标记" aria-label="Permalink to &quot;插入拍间隔标记&quot;">​</a></h3><p>每隔指定拍数插入一个「跳变标记对」：先跳到特殊角 <code>target</code>，再落回旋转 180° 的位置。</p><ul><li>标记对合计时长<strong>精确等于</strong>一块正常砖（节奏完全不变）</li><li>常用于在持续音 / 滑音中制造「打击感」或记号点</li><li>0 表示不插入；输入小于 1 自动按 1 处理，非整数自动取整</li></ul><h2 id="滑音缓速函数-30-种" tabindex="-1">滑音缓速函数（30 种） <a class="header-anchor" href="#滑音缓速函数-30-种" aria-label="Permalink to &quot;滑音缓速函数（30 种）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>缓速函数</th></tr></thead><tbody><tr><td>线性</td><td>Linear</td></tr><tr><td>正弦</td><td>InSine / OutSine / InOutSine</td></tr><tr><td>二次</td><td>InQuad / OutQuad / InOutQuad</td></tr><tr><td>三次</td><td>InCubic / OutCubic / InOutCubic</td></tr><tr><td>四次</td><td>InQuart / OutQuart / InOutQuart</td></tr><tr><td>五次</td><td>InQuint / OutQuint / InOutQuint</td></tr><tr><td>指数</td><td>InExpo / OutExpo / InOutExpo</td></tr><tr><td>圆</td><td>InCirc / OutCirc / InOutCirc</td></tr><tr><td>回弹</td><td>InBack / OutBack / InOutBack</td></tr><tr><td>弹性</td><td>InElastic / OutElastic / InOutElastic</td></tr><tr><td>弹跳</td><td>InBounce / OutBounce</td></tr></tbody></table><ul><li><strong>In</strong>：慢→快；<strong>Out</strong>：快→慢；<strong>InOut</strong>：两头慢中间快</li><li>缓速作用于<strong>频率</strong>（Hz）的线性插值：<code>freq(t) = startHz + (endHz - startHz) × Ease(t)</code></li><li>选择弹性 / 弹跳时频率会短暂<strong>超过终点值</strong>再回弹，适合夸张的滑音效果</li></ul><h2 id="语言与设置" tabindex="-1">语言与设置 <a class="header-anchor" href="#语言与设置" aria-label="Permalink to &quot;语言与设置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置项</th><th>说明</th></tr></thead><tbody><tr><td>英文 / 中文</td><td>切换面板语言（实时刷新，含字体）</td></tr><tr><td>启用频率轨道铺设工具</td><td>总开关，关闭后面板不显示、功能不生效</td></tr><tr><td>启用快捷打开 / 解除输入限制</td><td>同 Mod 的其它功能开关</td></tr><tr><td>启用频率轨道日志</td><td>输出应用/滑音/噪音详细日志、标记时间戳、面板布局（默认关闭，排查用）</td></tr></tbody></table><h2 id="使用技巧与常见问题" tabindex="-1">使用技巧与常见问题 <a class="header-anchor" href="#使用技巧与常见问题" aria-label="Permalink to &quot;使用技巧与常见问题&quot;">​</a></h2><ul><li><strong>音高不准？</strong> 确认频率输入正确，Mod 会自动变速（SetSpeed），游戏内显示 BPM = 频率 × 60。开启日志可看到 <code>变速: newBpm=..., 频率≈...Hz</code> 核对</li><li><strong>只生成极少块？</strong> 数量为 0 或为空时：应用/噪音按 1 块、滑音按 32 块处理</li><li><strong>想制造鼓点/记号？</strong> 用 <strong>插入拍间隔</strong>，节奏完全不变</li><li><strong>外圈 vs 内圈？</strong> 外圈每块拍数翻倍，同一频率下外圈圈数更少、视觉更大；音高一致</li><li><strong>滑音不滑？</strong> 确认终点频率与起始不同；选择非线性缓速（如弹性/弹跳）可强化渐变感</li><li><strong>面板不出现？</strong> 在编辑器里切换「角度输入模式」开关一次，或确认 Mod 总开关已启用</li><li><strong>日志不输出？</strong> 在 Mod 设置里勾选「启用频率轨道日志」</li></ul><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>仓库：<a href="https://github.com/adofaiex/ADOFAIMods" target="_blank" rel="noreferrer">adofaiex/ADOFAIMods</a>（EditorExtensions + InformationDisplay）</li><li>其余编辑器增强（CustomRotateAngle / DisableLimit / QuickOpen）也在此仓库，随 EditorExtensions 一起安装</li></ul>',46)])])}const b=r(e,[["render",d]]);export{u as __pageData,b as default};
